import { memo, useCallback } from 'react';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useUpdateUserInfo } from '~/entities/user/lib/use-update-user-info';
import { YesOrNo } from '~/shared/api/dtos/enums';
import { ToggleSwitch } from '~/shared/ui/toggle-switch/toggle-switch';

export const ToggleTokenAndPaymentNotification = memo(function ToggleTokenAndPayment() {
  const { updateUserInfo } = useUpdateUserInfo();
  const { data: userRes } = useGetUserInfoQuery();
  const processNtcnYn = userRes?.tbCstmrMastr?.processNtcnYn;

  const onToggleTokenAndPayment = useCallback(() => {
    updateUserInfo((prev) => ({
      processNtcnYn: prev.processNtcnYn === YesOrNo.예 ? YesOrNo.아니오 : YesOrNo.예,
    }));
  }, []);

  return <ToggleSwitch on={processNtcnYn === YesOrNo.예} onToggle={onToggleTokenAndPayment} />;
});
